<?php
if(!defined('ABSPATH'))exit;
function dgs_record_allowed($id){return current_user_can('dgs_manage_education')&&dgs_edu_role(absint($id),'dgs_student');}
function dgs_record_fields(){return array('father'=>'نام پدر','birth'=>'تاریخ تولد (شمسی)','gender'=>'جنسیت','birthplace'=>'محل تولد','nationality'=>'تابعیت','mother_phone'=>'موبایل مادر','home_phone'=>'تلفن منزل','address'=>'آدرس محل سکونت','guardian_name'=>'نام و نام خانوادگی ولی','relation'=>'نسبت ولی','guardian_national'=>'کد ملی ولی','occupation'=>'شغل ولی','workplace'=>'محل کار ولی','entry_year'=>'سال ورود به مدرسه','admission'=>'نحوه پذیرش','registration'=>'وضعیت ثبت‌نام');}
function dgs_record_birth($raw){$raw=str_replace('/','-',dgs_edu_digits($raw));if(!preg_match('/^(1[34][0-9]{2})-([0-9]{1,2})-([0-9]{1,2})$/D',$raw,$m))return false;$y=(int)$m[1];$mo=(int)$m[2];$da=(int)$m[3];if($mo<1||$mo>12||$da<1||$da>31)return false;$g=explode('-',dgs_att_gregorian($y,$mo,$da));return dgs_jalali_parts((int)$g[0],(int)$g[1],(int)$g[2])===array($y,$mo,$da);}
function dgs_record_save($id,$d){
 if(!dgs_record_allowed($id))return dgs_edu_error('access','دسترسی مجاز نیست.');if(!is_scalar($d['revision']??''))return dgs_edu_error('input','درخواست معتبر نیست.');$old=get_user_meta($id,'_dgs_record',true);$old=is_array($old)?$old:array();if((string)($d['revision']??'')!==(string)($old['revision']??0))return dgs_edu_error('stale','پرونده تغییر کرده؛ صفحه را تازه کنید.');$next=array();
 foreach(dgs_record_fields() as $k=>$label){if(!is_scalar($d[$k]??''))return dgs_edu_error('input','اطلاعات معتبر نیست.');$v=sanitize_text_field((string)($d[$k]??''));if(dgs_edu_length($v)>($k==='address'?500:120))return dgs_edu_error('length','طول اطلاعات بیش از حد مجاز است.');if(in_array($k,array('mother_phone','home_phone'),true)&&$v!==''){$v=dgs_edu_digits($v);if(!preg_match('/^0[0-9]{10}$/D',$v))return dgs_edu_error('phone','شماره تماس ۱۱ رقمی وارد کنید.');}if($k==='guardian_national'&&$v!==''&&!dgs_edu_national_id(dgs_edu_digits($v)))return dgs_edu_error('national','کد ملی ولی معتبر نیست.');if($k==='birth'&&$v!==''&&!dgs_record_birth($v))return dgs_edu_error('date','تاریخ تولد معتبر نیست.');$next[$k]=$v;}
 $next['revision']=($old['revision']??0)+1;$next['updated_by']=get_current_user_id();$next['updated_at']=current_time('mysql');$ok=$old?update_user_meta($id,'_dgs_record',$next,$old):add_user_meta($id,'_dgs_record',$next,true);if(!$ok)return dgs_edu_error('write','ذخیره انجام نشد؛ صفحه را تازه کنید.');dgs_edu_audit('student_record',$id);return 'اطلاعات پرونده ذخیره شد.';
}
function dgs_record_form($id,$year,$op){return '<form class="dge-form dsp-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_record','record_nonce',true,false).'<input type="hidden" name="action" value="dgs_record"><input type="hidden" name="operation" value="'.esc_attr($op).'"><input type="hidden" name="student_id" value="'.(int)$id.'"><input type="hidden" name="year" value="'.esc_attr($year).'">';}
add_action('admin_post_dgs_record',function(){
 if(($_SERVER['REQUEST_METHOD']??'')!=='POST'||!current_user_can('dgs_manage_education'))wp_die('دسترسی مجاز نیست.','',array('response'=>403));check_admin_referer('dgs_record','record_nonce');$d=wp_unslash($_POST);$id=absint($d['student_id']??0);$year=dgs_edu_year(is_string($d['year']??null)?$d['year']:'');if(!dgs_record_allowed($id)||!$year)wp_die('پرونده معتبر نیست.','',array('response'=>403));$op=$d['operation']??'';$result=dgs_edu_error('operation','عملیات معتبر نیست.');
 if($op==='profile')$result=dgs_record_save($id,$d);
 if($op==='document'){$title=is_string($d['title']??null)?sanitize_text_field($d['title']):'';if(!$title||dgs_edu_length($title)>120)$result=dgs_edu_error('title','عنوان مدرک را وارد کنید.');else{$f=dgs_hw_store($_FILES['document']??null);if(is_wp_error($f))$result=$f;else{$f['title']=$title;$f['token']=wp_generate_uuid4();$f['created_at']=current_time('mysql');$f['created_by']=get_current_user_id();if(add_user_meta($id,'_dgs_record_document',$f)){$result='مدرک خصوصی به پرونده اضافه شد.';dgs_edu_audit('student_document',$id);}else{@unlink(dgs_hw_dir().'/'.$f['stored_file']);$result=dgs_edu_error('write','ذخیره مدرک انجام نشد.');}}}}
 if($op==='discipline'){$note=is_string($d['note']??null)?sanitize_textarea_field($d['note']):'';$points=dgs_edu_digits(is_scalar($d['points']??null)?(string)$d['points']:'');$date=is_string($d['date']??null)?dgs_att_parse_day($d['date'],$year):false;if(!$note||dgs_edu_length($note)>500||!preg_match('/^-?[0-9]{1,3}$/D',$points)||abs((int)$points)>100||!$date)$result=dgs_edu_error('entry','تاریخ، شرح و امتیاز بین منفی ۱۰۰ تا مثبت ۱۰۰ وارد کنید.');else{$entry=array('year'=>$year,'date'=>$d['date'],'note'=>$note,'points'=>(int)$points,'by'=>get_current_user_id(),'created_at'=>current_time('mysql'));$result=add_user_meta($id,'_dgs_record_discipline',$entry)?'رویداد انضباطی ثبت شد.':dgs_edu_error('write','ثبت انجام نشد.');dgs_edu_audit('student_discipline',$id);}}
 $token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,array('error'=>is_wp_error($result),'text'=>is_wp_error($result)?$result->get_error_message():$result),300);wp_safe_redirect(add_query_arg('dg_notice',$token,dgs_school_url('records',$year,array('student_id'=>$id))),303);exit;
});
function dgs_record_document($id,$token){if(!dgs_record_allowed($id)||!is_string($token))return null;foreach(get_user_meta($id,'_dgs_record_document',false) as $f)if(is_array($f)&&($f['token']??'')===$token)return $f;return null;}
add_action('admin_post_dgs_record_file',function(){
 $id=absint($_GET['student_id']??0);if(!dgs_record_allowed($id))wp_die('دسترسی مجاز نیست.','',array('response'=>403));check_admin_referer('dgs_record_file');$f=dgs_record_document($id,$_GET['token']??'');if(!$f||!preg_match('/^[a-f0-9]{32}\.(pdf|png|jpe?g|docx|xlsx|pptx)$/D',$f['stored_file']))wp_die('مدرک موجود نیست.','',array('response'=>404));$path=dgs_hw_dir().'/'.$f['stored_file'];if(!is_file($path))wp_die('مدرک موجود نیست.','',array('response'=>404));nocache_headers();header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header('Content-Type: '.$f['file_mime']);header('Content-Disposition: attachment; filename="document.'.pathinfo($path,PATHINFO_EXTENSION).'"');header('Content-Length: '.filesize($path));while(ob_get_level())ob_end_clean();readfile($path);exit;
});
function dgs_record_card($title,$rows){$out='<section class="dsr-card"><h3>'.esc_html($title).'</h3><dl>';foreach($rows as $label=>$value)$out.='<div><dt>'.esc_html($label).'</dt><dd>'.esc_html($value!==''?(string)$value:'—').'</dd></div>';return $out.'</dl></section>';}
function dgs_edu_view_records($year){
 if(!current_user_can('dgs_manage_education'))return '';$id=absint(dgs_att_get('student_id'));if(!dgs_record_allowed($id))return '<div class="dsp-school">'.dgs_school_title('پرونده الکترونیکی دانش‌آموز','دانش‌آموز را از مدیریت آموزشی انتخاب کنید.').'<a class="dg-btn" href="'.esc_url(dgs_edu_url('education',$year)).'">فهرست دانش‌آموزان</a></div>';
 global $wpdb;$e=dgs_edu_tables();$u=get_userdata($id);$c=$wpdb->get_row($wpdb->prepare("SELECT c.* FROM {$e['enrollments']} en JOIN {$e['classes']} c ON c.id=en.class_id WHERE en.student_id=%d AND en.school_year=%s",$id,$year));$m=get_user_meta($id,'_dgs_record',true);$m=is_array($m)?$m:array();$name=$u->display_name;$code=get_user_meta($id,'_dgs_student_code',true)?:$id;$guardian=get_user_meta($id,'_dgs_guardian_phone',true);$events=array_values(array_filter(get_user_meta($id,'_dgs_record_discipline',false),function($v)use($year){return is_array($v)&&($v['year']??'')===$year;}));$docs=get_user_meta($id,'_dgs_record_document',false);$class=$c?$c->title:'—';$grade=$c?dgs_edu_grade_label($c->grade).' · '.(dgs_edu_fields()[$c->field]??''):'—';$series=dgs_school_grade_series($year,$id);$average=$series?number_format((float)$series[0]->average,2):'—';
 $out='<div class="dsp-school dsr-record" id="dsr-print">'.dgs_school_title('پرونده الکترونیکی دانش‌آموز','مشاهده و مدیریت اطلاعات تحصیلی، انضباطی، حضور و غیاب و مدارک دانش‌آموز').'<div class="dsp-actions dsr-tools"><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_edu_url('education',$year)).'">← بازگشت</a><button class="dg-btn dg-btn-outline" type="button" data-school-print="dsr-print">▣ چاپ پرونده</button><button class="dg-btn" type="button" data-school-dialog="dsr-edit">✎ ویرایش اطلاعات</button></div><section class="dsr-banner"><span class="dsr-avatar">'.dgs_school_icon('users').'</span><div><h2>'.esc_html($name).'</h2><small>دانش‌آموز</small></div><div>کد دانش‌آموزی<strong>'.esc_html(dgs_fa_digits($code)).'</strong></div><div>کلاس<strong>'.esc_html($class).'</strong></div><div>پایه و رشته<strong>'.esc_html($grade).'</strong></div></section><nav class="dsr-tabs">';foreach(array('identity'=>'مشخصات','grades'=>'نمرات','discipline'=>'انضباط','attendance'=>'حضور و غیاب','documents'=>'مدارک','finance'=>'مالی') as $anchor=>$label)$out.='<a href="#dsr-'.$anchor.'">'.esc_html($label).'</a>';$out.='</nav><div class="dsr-columns"><div id="dsr-identity">';
 $out.=dgs_record_card('▣ اطلاعات هویتی دانش‌آموز',array('نام و نام خانوادگی'=>$name,'نام پدر'=>$m['father']??'','کد ملی'=>$u->user_login,'تاریخ تولد'=>$m['birth']??'','جنسیت'=>$m['gender']??'','محل تولد'=>$m['birthplace']??'','تابعیت'=>$m['nationality']??''));
 $out.=dgs_record_card('☎ اطلاعات تماس',array('موبایل دانش‌آموز'=>get_user_meta($id,'_dgs_contact_phone',true),'موبایل پدر / ولی'=>$guardian,'موبایل مادر'=>$m['mother_phone']??'','تلفن منزل'=>$m['home_phone']??'','آدرس محل سکونت'=>$m['address']??''));
 $out.=dgs_record_card('♧ اطلاعات ولی (سرپرست قانونی)',array('نام و نام خانوادگی'=>$m['guardian_name']??'','نسبت با دانش‌آموز'=>$m['relation']??'','کد ملی'=>$m['guardian_national']??'','شغل'=>$m['occupation']??'','محل کار'=>$m['workplace']??'','شماره تماس'=>$guardian));
 $out.=dgs_record_card('▤ اطلاعات پذیرش و ثبت‌نام',array('سال ورود به مدرسه'=>$m['entry_year']??'','نحوه پذیرش'=>$m['admission']??'','وضعیت ثبت‌نام'=>$m['registration']??''));$out.='</div><div>';
 $out.='<div id="dsr-grades">'.dgs_record_card('♧ وضعیت تحصیلی و خلاصه عملکرد',array('پایه و رشته'=>$grade,'کلاس'=>$class,'سال تحصیلی'=>$year,'وضعیت کلاس'=>$c?($c->active?'فعال':'بایگانی'):'بدون انتساب','آخرین میانگین ماهانه منتشرشده'=>dgs_fa_digits($average))).'<p class="dsp-footnote">معدل رسمی نیمسال و کل سال هنوز ثبت نشده است.</p></div>';
 $sum=array_sum(array_column($events,'points'));$out.='<div id="dsr-discipline">'.dgs_record_card('♧ وضعیت انضباطی',array('جمع تغییر امتیازهای ثبت‌شده'=>$events?dgs_fa_digits($sum):'—','تعداد رویداد'=>dgs_fa_digits(count($events)))).'</div>';
 $a=dgs_att_tables();$stats=$wpdb->get_results($wpdb->prepare("SELECT r.status,COUNT(*) n FROM {$a['records']} r JOIN {$a['sessions']} s ON s.id=r.session_id JOIN {$e['classes']} c ON c.id=s.class_id WHERE r.student_id=%d AND c.school_year=%s GROUP BY r.status",$id,$year),OBJECT_K);$present=(int)($stats['present']->n??0);$late=(int)($stats['late']->n??0);$absent=(int)($stats['absent']->n??0);
 $out.='<div id="dsr-attendance">'.dgs_record_card('▦ آمار حضور و غیاب سال جاری',array('روزهای ثبت‌شده (بدون تعطیلی)'=>dgs_fa_digits($present+$late+$absent),'حاضر'=>dgs_fa_digits($present),'تأخیر'=>dgs_fa_digits($late),'غایب'=>dgs_fa_digits($absent))).'</div><section class="dsr-card"><h3>⚖ سوابق انضباطی</h3>'.dgs_edu_table_start(array('تاریخ','امتیاز','شرح مورد'));foreach(array_reverse($events) as $v)$out.='<tr><td>'.esc_html(dgs_fa_digits($v['date'])).'</td><td class="'.($v['points']<0?'dsr-negative':'dsr-positive').'">'.esc_html(dgs_fa_digits(($v['points']>0?'+':'').$v['points'])).'</td><td>'.esc_html($v['note']).'</td></tr>';$out.='</tbody></table></div>';if(!$events)$out.='<p>رویدادی ثبت نشده است.</p>';$out.='</section><section class="dsr-card" id="dsr-documents"><h3>▣ مدارک پذیرش و پرونده</h3><ul class="dsr-docs">';foreach($docs as $f){if(!is_array($f))continue;$url=wp_nonce_url(add_query_arg(array('action'=>'dgs_record_file','student_id'=>$id,'token'=>$f['token']),admin_url('admin-post.php')),'dgs_record_file');$out.='<li><span>✓</span><a href="'.esc_url($url).'">'.esc_html($f['title']).'</a><small>'.esc_html($f['file_name']).'</small></li>';}$out.='</ul>';if(!$docs)$out.='<p>هنوز مدرکی بارگذاری نشده است.</p>';$out.='</section></div></div>';
 $account=dgs_fin_get($id,$year);$out.='<div id="dsr-finance">'.dgs_record_card('▣ خلاصه مالی (تومان)',array('شهریه خالص'=>$account?dgs_fin_format($account->tuition-$account->discount):'—','پرداخت‌شده'=>$account?dgs_fin_format(dgs_fin_paid($account)):'—','مانده'=>$account?dgs_fin_format($account->tuition-$account->discount-dgs_fin_paid($account)):'—')).'</div>';
 $out.='<details class="dsr-card dsr-tools"><summary>افزودن رویداد انضباطی یا مدرک خصوصی</summary><div class="dsp-grid-two">'.dgs_record_form($id,$year,'discipline').'<h3>رویداد انضباطی</h3><label>تاریخ شمسی<input name="date" required placeholder="1405-08-20"></label><label>تغییر امتیاز<input name="points" type="number" min="-100" max="100" required></label><label>شرح<textarea name="note" maxlength="500" required></textarea></label><button class="dg-btn">ثبت رویداد</button></form>'.dgs_record_form($id,$year,'document').'<h3>مدرک خصوصی</h3><label>عنوان مدرک<input name="title" maxlength="120" required></label><label>فایل<input name="document" type="file" accept=".pdf,.png,.jpg,.jpeg,.docx,.xlsx,.pptx" required></label><p>حداکثر ۲۰ مگابایت؛ محدود به سقف هاست.</p><button class="dg-btn">ثبت مدرک</button></form></div></details>';
 $out.='<dialog class="dsp-dialog" id="dsr-edit"><button type="button" class="dsp-dialog-close" data-school-close>×</button><h3>ویرایش اطلاعات پرونده</h3>'.dgs_record_form($id,$year,'profile').'<input type="hidden" name="revision" value="'.(int)($m['revision']??0).'"><p>نام و تلفن دانش‌آموز/ولی از ویرایش مشخصات در مدیریت آموزشی تغییر می‌کند. نام کاربری ثابت است.</p><div class="dge-grid">';foreach(dgs_record_fields() as $k=>$label)$out.='<label>'.esc_html($label).'<input name="'.esc_attr($k).'" maxlength="'.($k==='address'?500:120).'" value="'.esc_attr($m[$k]??'').'"></label>';return $out.'</div><button class="dg-btn">ذخیره اطلاعات</button></form></dialog></div>';
}
add_action('wp_enqueue_scripts',function(){if(!dgs_is_role_portal()||dgs_portal_tab()!=='records')return;wp_add_inline_style('dgs-school-panels',file_get_contents(DGS_PATH.'assets/student-record.css'));},30);

add_action('template_redirect',function(){if(dgs_is_role_portal()&&dgs_portal_tab()==='records')nocache_headers();});
